package com.panish.ridebooking.ride.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.panish.ridebooking.events.RideCreatedEvent;import com.panish.ridebooking.ride.domain.OutboxEvent;import com.panish.ridebooking.ride.repository.OutboxEventRepository;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Component public class OutboxPublisher {private final OutboxEventRepository repo;private final KafkaTemplate<String,Object> kafka;private final ObjectMapper mapper;public OutboxPublisher(OutboxEventRepository r,KafkaTemplate<String,Object> k,ObjectMapper m){repo=r;kafka=k;mapper=m;}@Scheduled(fixedDelayString="${outbox.poll-ms:1000}") public void publish(){for(OutboxEvent e:repo.findTop100ByPublishedFalseOrderByCreatedAtAsc()){try{RideCreatedEvent event=mapper.readValue(e.getPayload(),RideCreatedEvent.class);kafka.send(e.getTopic(),String.valueOf(event.rideId()),event).get();markPublished(e.getId());}catch(Exception ex){System.err.println("Outbox publish failed for "+e.getId()+": "+ex.getMessage());}}}@Transactional public void markPublished(String id){repo.findById(id).ifPresent(e->{e.markPublished();repo.save(e);});}}